    private fun dynamicText(value: String, language: String): String? {
        val healthPrefix = "Vacunas, revisiones y cuidados de "
        val healthSuffix = " en un solo lugar."
        if (value.startsWith(healthPrefix) && value.endsWith(healthSuffix)) {
            val pet = value.removePrefix(healthPrefix).removeSuffix(healthSuffix)
            return when (language) {
                "en" -> "Vaccinations, check-ups and care for " + pet + ", all in one place."
                "ca" -> "Vacunes, revisions i cures de " + pet + ", tot en un sol lloc."
                "fr" -> "Vaccins, contrôles et soins de " + pet + ", tout au même endroit."
                "eu" -> pet + " txertoak, azterketak eta zaintzak leku berean."
                else -> null
            }
        }
        val sharedInvitation = Regex("^(.+?) quiere compartir contigo el perfil de (.+)\\.$").matchEntire(value)
        if (sharedInvitation != null) {
            val person = sharedInvitation.groupValues[1]
            val pet = sharedInvitation.groupValues[2]
            return when (language) {
                "en" -> "$person wants to share $pet's profile with you."
                "ca" -> "$person vol compartir amb tu el perfil de $pet."
                "fr" -> "$person souhaite partager avec vous le profil de $pet."
                "eu" -> "$person erabiltzaileak $pet-ren profila zurekin partekatu nahi du."
                else -> null
            }
        }
        val prefixes = when (language) {
            "eu" -> listOf(
                "Perfil compartido · " to "Partekatutako profila · ",
                "Vacunas, revisiones y cuidados de " to "Txertoak, azterketak eta zaintzak: ",
                "Una selección para " to "Hautaketa bat: ",
                "Eliminar perfil de " to "Ezabatu profila: ",
                "Compartir el perfil de " to "Partekatu profila: ",
                "Zona: " to "Eremua: ",
                "Contacto: " to "Kontaktua: ",
                "Foto de " to "Argazkia: ",
                "Aviso programado para " to "Abisua honetarako programatuta: ",
                "Un día bonito\\ncon " to "Egun polit bat\\n"
            )
            "en" -> listOf(
                "Perfil compartido · " to "Shared profile · ",
                "Vacunas, revisiones y cuidados de " to "Vaccinations, check-ups and care for ",
                "Una selección para " to "A selection for ",
                "Eliminar perfil de " to "Delete profile for ",
                "Compartir el perfil de " to "Share the profile of ",
                "Zona: " to "Area: ",
                "Contacto: " to "Contact: ",
                "Foto de " to "Photo of ",
                "Aviso programado para " to "Reminder set for ",
                "Un día bonito\ncon " to "A lovely day\nwith "
            )
            "ca" -> listOf(
                "Perfil compartido · " to "Perfil compartit · ",
                "Vacunas, revisiones y cuidados de " to "Vacunes, revisions i cures de ",
                "Una selección para " to "Una selecció per a ",
                "Eliminar perfil de " to "Elimina el perfil de ",
                "Compartir el perfil de " to "Comparteix el perfil de ",
                "Zona: " to "Zona: ",
                "Contacto: " to "Contacte: ",
                "Foto de " to "Foto de ",
                "Aviso programado para " to "Avís programat per a ",
                "Un día bonito\ncon " to "Un dia bonic\namb "
            )
            "fr" -> listOf(
                "Perfil compartido · " to "Profil partagé · ",
                "Vacunas, revisiones y cuidados de " to "Vaccins, contrôles et soins de ",
                "Una selección para " to "Une sélection pour ",
                "Eliminar perfil de " to "Supprimer le profil de ",
                "Compartir el perfil de " to "Partager le profil de ",
                "Zona: " to "Zone : ",
                "Contacto: " to "Contact : ",
                "Foto de " to "Photo de ",
                "Aviso programado para " to "Rappel programmé pour ",
                "Un día bonito\ncon " to "Une belle journée\navec "
            )
            else -> emptyList()
        }
        prefixes.firstOrNull { (source, _) -> value.startsWith(source) }?.let { (source, target) ->
            return target + value.removePrefix(source)
        }
        return when (language) {
            "eu" -> when {
                value.endsWith(" lugares guardados") -> value.removeSuffix(" lugares guardados") + " leku gordeta"
                Regex("^\\d+ registros$").matches(value) -> value.removeSuffix(" registros") + " erregistro"
                else -> null
            }
            "en" -> when {
                value.endsWith(" lugares guardados") -> value.removeSuffix(" lugares guardados") + " saved places"
                Regex("^\\d+ registros$").matches(value) -> value.removeSuffix(" registros") + " records"
                Regex("^\\d+ de \\d+ marcadas como hechas$").matches(value) -> value.replace(" de ", " of ").replace(" marcadas como hechas", " completed")
                else -> null
            }
            "ca" -> when {
                value.endsWith(" lugares guardados") -> value.removeSuffix(" lugares guardados") + " llocs desats"
                Regex("^\\d+ registros$").matches(value) -> value.removeSuffix(" registros") + " registres"
                else -> null
            }
            "fr" -> when {
                value.endsWith(" lugares guardados") -> value.removeSuffix(" lugares guardados") + " lieux enregistrés"
                Regex("^\\d+ registros$").matches(value) -> value.removeSuffix(" registros") + " entrées"
                else -> null
            }
            else -> null
        }
    }

    fun locale(language: String): Locale = when (language) {
        "ca" -> Locale("ca", "ES")
        "fr" -> Locale.FRANCE
        "en" -> Locale.UK
        "eu" -> Locale.forLanguageTag("eu-ES")
        else -> Locale("es", "ES")
    }

    fun text(value: String, language: String): String = when (language) {
        "eu" -> euUi[value] ?: eventTranslations["eu"]?.get(value) ?: featureUi["eu"]?.get(value) ?: dynamicText(value, language) ?: value
        "ca" -> ca[value] ?: caExtra[value] ?: caUi[value] ?: miscCa[value] ?: careCa[value] ?: accountExtra[language]?.get(value) ?: eventTranslations[language]?.get(value) ?: featureUi[language]?.get(value) ?: dynamicText(value, language) ?: value
        "fr" -> fr[value] ?: frExtra[value] ?: frUi[value] ?: miscFr[value] ?: careFr[value] ?: accountExtra[language]?.get(value) ?: eventTranslations[language]?.get(value) ?: featureUi[language]?.get(value) ?: dynamicText(value, language) ?: value
        "en" -> en[value] ?: enExtra[value] ?: enUi[value] ?: miscEn[value] ?: careEn[value] ?: accountExtra[language]?.get(value) ?: eventTranslations[language]?.get(value) ?: featureUi[language]?.get(value) ?: dynamicText(value, language) ?: value
        else -> value
    }
}
